/**
 * Labelled listing-vs-catalogue pairs for the matcher (Phase 2).
 *
 * Labels were written BEFORE the matcher was implemented, from the product definition in
 * CLAUDE.md: EXACT needs brand + variant + normalised size + unit equal (GTIN first); a
 * different size is never a match; a different brand is SUBSTITUTE; anything the rules cannot
 * confirm is at most LIKELY; ambiguity or a clash is UNMATCHED. If the matcher disagrees with a
 * label, fix the matcher, not the label.
 *
 * The catalogue is the seeded 40-product set (server/src/seed/data.ts).
 */
import type { MatchStatus } from '../../models/enums';

export interface LabelledPair {
  id: string;
  title: string;
  brand?: string;
  packSize?: string;
  gtin?: string;
  expected: MatchStatus;
  /** Seed product key the listing should map to; null when expected is UNMATCHED. */
  expectedKey: string | null;
  note: string;
}

