/**
 * Adversarial probes written AFTER the matcher existed, labelled from product sense only.
 * The first run found one miss (P26: "Dish Wash" vs "Dishwash"); the matcher was fixed, the label was not.
 */
const probe = (
  id: string,
  title: string,
  expected: LabelledPair['expected'],
  expectedKey: string | null,
  note: string,
  extra: Partial<LabelledPair> = {},
): LabelledPair => ({ id, title, expected, expectedKey, note, ...extra });

